const types = table(['Type', 'One-sided limits', 'Value', 'Can it be removed?'], [['Removable', 'equal and finite', 'missing or different', 'yes: redefine $f(a)$'], ['Jump', 'finite but unequal', 'any', 'no'], ['Infinite', 'at least one is infinite', 'any', 'no']], 'Table of the three kinds of discontinuity: removable when the limit exists but the value is missing or different; jump when the one-sided limits are finite but unequal; infinite when a one-sided limit is infinite. Only the first can be removed.', 'Look at the one-sided limits first.');
const pHole = plot({ x: [0, 7], y: [0, 12], fns: [{ expr: 'x + 4', label: '$y = x + 4$, $x \\ne 4$' }], pts: [[4, 5, 'stored g(4) = 5', 'free']] }, 'Graph of g of x equal to x squared minus 16 over x minus 4, which is the line y equals x plus 4 with the point at x equals 4 missing from the line; the stored value g of 4 equals 5 sits below the line, away from the height 8 that the line approaches.', 'The line approaches $8$ at $x = 4$, but the stored value is $5$: a removable discontinuity.');
pHole.spec.points[0].on_curve = false; // the stored value deliberately sits off the line
must(kind((x) => (x === 4 ? 5 : (x * x - 16) / (x - 4)), 4, 5) === 'removable', 'pHole');
const pJump = plot({ x: [-1, 3], y: [-2, 2], fns: [{ expr: '-1', label: '$y = -1$ for $x < 1$', domain: [-1, 0.999] }, { expr: '1', label: '$y = 1$ for $x > 1$', domain: [1, 3] }], pts: [[1, 1, 'h(1) = 1']] }, 'Graph of h of x equal to mod of x minus 1 over x minus 1: a horizontal segment at height minus 1 to the left of x equals 1 and a horizontal segment at height 1 to the right, with the value h of 1 equal to 1 marked. The graph jumps by 2 at x equals 1.', 'Left-hand limit $-1$, right-hand limit $1$: a jump.');
must(kind((x) => (x === 1 ? 1 : Math.abs(x - 1) / (x - 1)), 1, 1) === 'jump', 'pJump');
const pInf = plot({ x: [-5, 1], y: [0, 12], fns: [{ expr: '1/(x + 2)^2', label: '$y = \\dfrac{1}{(x + 2)^2}$', domain: [-5, -2.3] }, { expr: '1/(x + 2)^2', domain: [-1.7, 1] }], pts: [[-3, 1, '(-3, 1)'], [-1, 1, '(-1, 1)']] }, 'Graph of y equals 1 over x plus 2 squared: two branches that rise steeply on both sides of the vertical line x equals minus 2, passing through (minus 3, 1) and (minus 1, 1). The values grow without bound near minus 2.', 'Near $x = -2$ the values grow without bound: an infinite discontinuity.');
