const diffFlow = flow('LR', [['l', 'Left-hand derivative $\\lim_{h \\to 0^-}\\dfrac{f(a + h) - f(a)}{h}$'], ['r', 'Right-hand derivative $\\lim_{h \\to 0^+}\\dfrac{f(a + h) - f(a)}{h}$'], ['q', 'Equal and finite?'], ['y', 'Differentiable: $f\'(a)$ is the common value']], [['l', 'q'], ['r', 'q'], ['q', 'y']], 'Flow for testing differentiability at a point: find the left-hand derivative and the right-hand derivative; if they are finite and equal, the function is differentiable and the derivative is the common value.', 'Differentiable means the two one-sided slopes agree.');
const pAbs = plot({ x: [-3, 3], y: [-1, 3], fns: [{ expr: 'abs(x)', label: '$y = |x|$' }], pts: [[-1, 1, '(-1, 1)'], [1, 1, '(1, 1)']] }, 'Graph of y equals mod x: a V shape with its tip at the origin, slope minus 1 on the left through (minus 1, 1) and slope 1 on the right through (1, 1).', 'Continuous at $0$, but the slopes $-1$ and $1$ differ: a corner, not differentiable.');
