const summary1 = flow('LR', [['c', 'Continuous: both limits $= f(a)$'], ['t', 'Removable / jump / infinite'], ['d', 'Differentiable: both slopes equal'], ['i', 'Differentiable $\\Rightarrow$ continuous']], [['c', 't'], ['t', 'd'], ['d', 'i']], 'Summary flow of Part 1: continuity needs both one-sided limits equal to the value; breaks are removable, jumps or infinite; differentiability needs equal one-sided slopes; and differentiability implies continuity.', 'Part 1 in one line.');
const tips1 = table(['Question type', 'How ISC marks are usually given'], [['Find $k$ for continuity (2)', 'both one-sided limits 1, equation and $k$ 1'], ['Classify a discontinuity (2–3)', 'limits 1, type with reason 1, repair 1'], ['Differentiability test (3–5)', 'continuity 1, each one-sided derivative 1, conclusion 1'], ['Smooth join (3)', 'value equation 1, slope equation 1, constants 1']], 'Exam tips table: finding k earns marks for the limits and the equation; classifying a discontinuity needs the limits, the type with reason and the repair; a differentiability test needs continuity and both one-sided derivatives; a smooth join needs a value equation and a slope equation.', 'Write each one-sided limit or derivative separately: each carries a mark.');

